import Icon from "@/core/components/primitives/icon/icon";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import styles from "./used-voucher-code.module.less";
import { useTranslation } from "react-i18next";
import { LabelKey } from "../../../labels/i18n";

type Props = {
  /** The voucher code to display */
  code: string;
  /** Visual variant to indicate the state of the voucher code */
  variant: "success" | "error";
  /** Whether the delete button should be disabled */
  disabled: boolean;
  /** Callback function triggered when the delete button is clicked */
  onDelete: () => void;
  /** Optional description that can be either plain text or a translatable label */
  description?: { type: "description"; text: string } | { type: "label"; labelKey: LabelKey };
};

export const UsedVoucherCode = ({ code, variant, disabled, onDelete, description }: Props) => {
  const { t } = useTranslation();

  return (
    <div data-variant={variant} className={styles.wrapper}>
      <div>
        <div className={styles.codeRow}>
          <Icon name="discount" />
          <p className="bold">{code}</p>
        </div>
        {description && description.type === "description" && <p>{description.text}</p>}
        {description && description.type === "label" && <p>{t(description.labelKey)}</p>}
      </div>
      <div className={styles.buttonWrapper}>
        <PrimaryButton
          className={styles.button}
          complementary
          iconCenterNew="trash"
          ariaLabel={t("removeVoucherCode", { code })}
          onClick={onDelete}
          isDisabled={disabled}
        />
      </div>
    </div>
  );
};
